{
  "гриб": "Amanita phalloides (бледная поганка)",
  "состав": [
    {
      "вещество": "α-аманитин (α-amanitin)",
      "содержание": "250–400 мг/кг (свежий вес)",
      "влияние": "Необратимо ингибирует РНК-полимеразу II, останавливая транскрипцию и вызывая некроз гепатоцитов и нефроцитов."
    },
    {
      "вещество": "β-аманитин (β-amanitin)",
      "содержание": "50–100 мг/кг (свежий вес)",
      "влияние": "Блокирует РНК-полимеразы II и III, менее токсичен, чем α-аманитин, но также повреждает печень и почки."
    },
    {
      "вещество": "α-фаллоидин (α-phalloidin)",
      "содержание": "100–200 мг/кг (свежий вес)",
      "влияние": "Надёжно связывает F-актин, нарушает цитоскелет и вызывает цитотоксическую гибель клеток."
    },
    {
      "вещество": "β-фаллоидин (β-phalloidin)",
      "содержание": "50–100 мг/кг (свежий вес)",
      "влияние": "Диссоциирует актиновые микроволокна, проявляет цитотоксическое действие на клеточные мембраны."
    },
    {
      "вещество": "γ-фаллоидин (γ-phalloidin)",
      "содержание": "30–80 мг/кг (свежий вес)",
      "влияние": "Взаимодействует с актином, но в меньшей степени, чем α-фаллоидин, и слабо выражает цитотоксичность."
    }
  ]
}

{
  "гриб": "Amanita rubescens (мухомор серо-розовый / мухомор розоватый)",
  "состав": [
    {
      "вещество": "Мусцимол (muscimol, 4-hydroxy-2-pyrrolidinone / циклический аналог ГАМК)",
      "содержание": "≈ 0,01–0,3 % от сухого веса (значительно меньше, чем в A. muscaria)",
      "влияние": "Агонист ГАМК-A рецепторов, вызывает лёгкое угнетение ЦНС, сонливость и лёгкую дизориентацию."
    },
    {
      "вещество": "Иботеновая кислота (ibotenic acid, 2-carboxy-3-[(1-amino-1-carboxyethyl)amino]propionic acid)",
      "содержание": "≈ 0,02–0,1 % от сухого веса (пропредрок мусцимола)",
      "влияние": "Агонист глутаматных NMDA/AMPA рецепторов, способна провоцировать лёгкую спутанность сознания и подрагивание мышц."
    },
    {
      "вещество": "α-Аманитин (α-amanitin, 8,9-ангидро-5,6-аза-1,4,7,10-тетраксациклотетрадекан-2,11-дион)",
      "содержание": "следовые количества / < 0,001 % от сухого веса (секция Validae, в отличие от секции Lepiota)",
      "влияние": "При наличии ингибирует РНК-полимеразу II, однако в A. rubescens концентрации слишком малы для тяжёлого гепатотоксического эффекта."
    },
    {
      "вещество": "Хитин и другие структурные полисахариды (β-глюканы, маннан)",
      "содержание": "≈ 15–25 % от сухого веса",
      "влияние": "Несут структурную функцию клеточной стенки; для человека являются неперевариваемой пищевыми ферментами клетчатоподобной фракцией."
    },
    {
      "вещество": "Гликоген (α-1,4-гликозиды)",
      "содержание": "≈ 2–5 % от сухого веса",
      "влияние": "Служит источником энергии для гриба; после термической обработки частично расщепляется и усваивается как простые сахара."
    },
    {
      "вещество": "Эргостерол и другие стеролы (ланостерол, фангерол)",
      "содержание": "≈ 0,5–2 % от сухого веса",
      "влияние": "Непосредственного токсического действия не оказывают; эргостерол фотохимически превращается в провитамин D₂."
    },
    {
      "вещество": "Белки и пищеварительные ферменты (пептидазы, хитиназы, пероксидазы)",
      "содержание": "≈ 30–45 % от сухого веса (по сухому веществу)",
      "влияние": "Обеспечивают метаболизм гриба; в сыром виде некоторые фермативные белки могут вызывать лёгкое раздражение ЖКТ."
    },
    {
      "вещество": "Витамины группы B (рибофлавин, ниацин, тиамин) и аскорбиновая кислота",
      "содержание": "рибофлавин ≈ 5–10 мг/кг сухого веса; ниацин ≈ 10–30 мг/кг",
      "влияние": "Участие в коферментных реакциях; в обычных пищевых дозах токсическим действием не обладают."
    },
    {
      "вещество": "Минеральные элементы (K, P, Mg, Ca, Fe, Cu, Zn)",
      "содержание": "K ≈ 1–2 % от сухого веса; P ≈ 0,5–1 %",
      "влияние": "Составляющие электролитного баланса; в умеренных количествах не вызывают отравления."
    },
    {
      "вещество": "Фенольные соединения и летучие ароматические вещества (метилквотинолы, гексаналь)",
      "содержание": "неизвестно (следовые, < 0,1 % от сухого веса)",
      "влияние": "Обеспечивают характерный «мухоморный» запах; в пищевых концентрациях фармакологически незначимы."
    }
  ]
}
